def gram_schmidt(vectors):
    basis = []
    for v in vectors:
        w = v.astype(float).copy()
        for b in basis:
            w -= (np.dot(v, b) / np.dot(b, b)) * b   # subtract the overlap with each earlier direction
        basis.append(w)
    return basis

result = gram_schmidt([np.array([1, 1]), np.array([1, 0])])
print(np.dot(result[0], result[1]))   # 0, now orthogonal
